CREATE TABLE IF NOT EXISTS math_candidate_solution_results (id TEXT PRIMARY KEY, problem_id TEXT NOT NULL REFERENCES math_problems(id), parse_result_id TEXT NOT NULL REFERENCES math_parse_results(id), build_result_id TEXT NOT NULL REFERENCES math_sympy_build_results(id), analysis_report_id TEXT NOT NULL REFERENCES math_analysis_reports(id), input_source_revision INTEGER NOT NULL, input_hash TEXT NOT NULL, solver_id TEXT NOT NULL, solver_version TEXT NOT NULL, sympy_version TEXT NOT NULL, status TEXT NOT NULL, problem_classification TEXT NOT NULL, candidate_result_json TEXT NOT NULL, constraints_snapshot_json TEXT NOT NULL, warnings_json TEXT NOT NULL DEFAULT '[]', errors_json TEXT NOT NULL DEFAULT '[]', duration_ms INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(problem_id,analysis_report_id,input_hash,solver_id,solver_version,sympy_version));
CREATE INDEX IF NOT EXISTS idx_math_candidate_current ON math_candidate_solution_results(problem_id,input_source_revision,created_at);
